-- Phase O: durable Security & Compliance control plane.
create table if not exists public.security_policies (id uuid primary key default gen_random_uuid(), policy_key text not null unique, version integer not null default 1 check (version > 0), status text not null default 'active' check (status in ('draft','active','disabled','retired')), priority integer not null default 100 check (priority >= 0), action_pattern text not null default '.*', resource_type_pattern text not null default '.*', effect text not null check (effect in ('allow','deny','approval')), severity text not null default 'low' check (severity in ('low','medium','high','critical')), conditions jsonb not null default '{}'::jsonb, description text not null default '', created_by uuid references auth.users(id), updated_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.security_requests (id uuid primary key default gen_random_uuid(), idempotency_key text not null unique, actor_id uuid references auth.users(id), agent_key text, action text not null, resource_type text, resource_id text, task_id uuid references public.tasks(id), run_id uuid references public.task_runs(id), context jsonb not null default '{}'::jsonb, decision text not null check (decision in ('allow','deny','approval_required')), reason text not null, matched_policy_ids uuid[] not null default '{}'::uuid[], evaluated_at timestamptz not null default now(), expires_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.security_events (id uuid primary key default gen_random_uuid(), event_type text not null, severity text not null check (severity in ('low','medium','high','critical')), actor_id uuid references auth.users(id), agent_key text, action text, resource_type text, resource_id text, task_id uuid references public.tasks(id), run_id uuid references public.task_runs(id), request_id uuid references public.security_requests(id), message text not null, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists public.security_incidents (id uuid primary key default gen_random_uuid(), incident_key text not null unique, incident_type text not null, severity text not null check (severity in ('low','medium','high','critical')), status text not null default 'open' check (status in ('open','investigating','contained','resolved','false_positive')), title text not null, description text not null default '', source_event_id uuid references public.security_events(id), actor_id uuid references auth.users(id), agent_key text, assigned_to uuid references auth.users(id), containment jsonb not null default '{}'::jsonb, resolution text, metadata jsonb not null default '{}'::jsonb, opened_at timestamptz not null default now(), contained_at timestamptz, resolved_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists security_policies_match_idx on public.security_policies(status, priority desc); create index if not exists security_requests_actor_idx on public.security_requests(actor_id, created_at desc); create index if not exists security_requests_task_idx on public.security_requests(task_id, created_at desc); create index if not exists security_events_actor_idx on public.security_events(actor_id, created_at desc); create index if not exists security_events_severity_idx on public.security_events(severity, created_at desc); create index if not exists security_incidents_status_idx on public.security_incidents(status, severity, updated_at desc);
alter table public.security_policies enable row level security; alter table public.security_requests enable row level security; alter table public.security_events enable row level security; alter table public.security_incidents enable row level security;
revoke all on public.security_policies, public.security_requests, public.security_events, public.security_incidents from anon, authenticated; grant select on public.security_policies to authenticated; grant select on public.security_requests, public.security_events to authenticated; grant select on public.security_incidents to authenticated; grant all on public.security_policies, public.security_requests, public.security_events, public.security_incidents to service_role;
create policy security_policies_admin_select on public.security_policies for select to authenticated using ((select public.has_role((select auth.uid()), 'admin')));
create policy security_requests_owner_select on public.security_requests for select to authenticated using ((select auth.uid()) = actor_id or (select public.has_role((select auth.uid()), 'admin')));
create policy security_events_owner_select on public.security_events for select to authenticated using ((select auth.uid()) = actor_id or (select public.has_role((select auth.uid()), 'admin')));
create policy security_incidents_admin_select on public.security_incidents for select to authenticated using ((select public.has_role((select auth.uid()), 'admin')));
revoke update, delete on public.security_events from service_role; revoke update, delete on public.security_requests from service_role;
create or replace function public.security_authorize_action(p_idempotency_key text,p_actor_id uuid,p_agent_key text,p_action text,p_resource_type text default null,p_resource_id text default null,p_task_id uuid default null,p_run_id uuid default null,p_context jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path=public as $$ declare existing public.security_requests; policy_row public.security_policies; decision text := 'deny'; reason text := 'No active security policy matched the requested action'; matched uuid[] := '{}'::uuid[]; req public.security_requests; event_severity text := 'medium'; begin select * into existing from public.security_requests where idempotency_key=p_idempotency_key limit 1; if found then return jsonb_build_object('allowed',existing.decision='allow','requires_approval',existing.decision='approval_required','decision',existing.decision,'reason',existing.reason,'request_id',existing.id,'policy_ids',existing.matched_policy_ids); end if; select * into policy_row from public.security_policies where status='active' and p_action ~ action_pattern and coalesce(p_resource_type,'') ~ resource_type_pattern order by priority desc,version desc,created_at desc limit 1; if found then matched:=array[policy_row.id]; if policy_row.effect='allow' then decision:='allow'; reason:=policy_row.description; event_severity:='low'; elsif policy_row.effect='approval' then decision:='approval_required'; reason:=policy_row.description; event_severity:='medium'; else decision:='deny'; reason:=policy_row.description; event_severity:=policy_row.severity; end if; end if; insert into public.security_requests(idempotency_key,actor_id,agent_key,action,resource_type,resource_id,task_id,run_id,context,decision,reason,matched_policy_ids,expires_at) values(p_idempotency_key,p_actor_id,p_agent_key,p_action,p_resource_type,p_resource_id,p_task_id,p_run_id,coalesce(p_context,'{}'::jsonb),decision,coalesce(nullif(reason,''),'Security policy decision'),matched,case when decision='approval_required' then now()+interval '15 minutes' else null end) returning * into req; insert into public.security_events(event_type,severity,actor_id,agent_key,action,resource_type,resource_id,task_id,run_id,request_id,message,metadata) values('policy.decision',event_severity,p_actor_id,p_agent_key,p_action,p_resource_type,p_resource_id,p_task_id,p_run_id,req.id,'Security policy evaluated',jsonb_build_object('decision',decision,'policy_ids',matched)); return jsonb_build_object('allowed',decision='allow','requires_approval',decision='approval_required','decision',decision,'reason',reason,'request_id',req.id,'policy_ids',matched); end; $$;
revoke all on function public.security_authorize_action(text,uuid,text,text,text,text,uuid,uuid,jsonb) from public, anon, authenticated; grant execute on function public.security_authorize_action(text,uuid,text,text,text,text,uuid,uuid,jsonb) to service_role;
create or replace function public.create_security_incident(p_incident_key text,p_incident_type text,p_severity text,p_title text,p_description text default '',p_source_event_id uuid default null,p_actor_id uuid default null,p_agent_key text default null,p_metadata jsonb default '{}'::jsonb) returns public.security_incidents language plpgsql security definer set search_path=public as $$ declare row public.security_incidents; begin insert into public.security_incidents(incident_key,incident_type,severity,title,description,source_event_id,actor_id,agent_key,metadata) values(p_incident_key,p_incident_type,p_severity,p_title,p_description,p_source_event_id,p_actor_id,p_agent_key,coalesce(p_metadata,'{}'::jsonb)) on conflict(incident_key) do update set updated_at=now() returning * into row; return row; end; $$;
revoke all on function public.create_security_incident(text,text,text,text,text,uuid,uuid,text,jsonb) from public,anon,authenticated; grant execute on function public.create_security_incident(text,text,text,text,text,uuid,uuid,text,jsonb) to service_role;
insert into public.security_policies(policy_key,version,status,priority,action_pattern,resource_type_pattern,effect,severity,description) values ('phase-o.default-allow',1,'active',1,'.*','.*','allow','low','Default platform security policy; existing permission boundaries remain authoritative.'),('phase-o.roles-deny',1,'active',1000,'^(roles\\.|permissions\\.|security\\.policy\\.).*','.*','deny','critical','Role, permission and security-policy self-modification is prohibited through agent actions.'),('phase-o.secrets-approval',1,'active',900,'^(secrets\\.|credentials\\.).*','.*','approval','high','Credential and secret operations require an explicit human approval gate.'),('phase-o.data-export-approval',1,'active',800,'^(data\\.export|knowledge\\.publish|knowledge\\.rollback).*','.*','approval','high','Sensitive data export and production knowledge mutation require human approval.'),('phase-o.agent-lifecycle-approval',1,'active',700,'^agent\\.(activate|disable|rollback|version\\.).*','agent','approval','high','Agent lifecycle changes require human approval.'),('phase-o.audit-deny',1,'active',650,'^(audit\\.delete|audit\\.purge|security\\.event\\.delete).*','.*','deny','critical','Security audit records are append-only and cannot be purged by agents.'),('phase-o.sandbox-allow',1,'active',100,'^sandbox\\.(open|close|inspect).*','.*','allow','low','Bounded agent sandbox operations are allowed subject to Phase M permissions and TTL controls.') on conflict(policy_key) do update set version=excluded.version,status=excluded.status,priority=excluded.priority,action_pattern=excluded.action_pattern,resource_type_pattern=excluded.resource_type_pattern,effect=excluded.effect,severity=excluded.severity,description=excluded.description,updated_at=now();
insert into public.agent_permissions(agent_id,permission,allowed,requires_approval) select id,'security.inspect',true,false from public.agents where agent_key='security' on conflict(agent_id,permission) do update set allowed=true,requires_approval=false;
insert into public.agent_permissions(agent_id,permission,allowed,requires_approval) select id,'violations.flag',true,false from public.agents where agent_key='security' on conflict(agent_id,permission) do update set allowed=true,requires_approval=false;
insert into public.agent_permissions(agent_id,permission,allowed,requires_approval) select id,'security.incident.create',true,false from public.agents where agent_key='security' on conflict(agent_id,permission) do update set allowed=true,requires_approval=false;
insert into public.agent_permissions(agent_id,permission,allowed,requires_approval) select id,'security.policy.evaluate',true,false from public.agents where agent_key='security' on conflict(agent_id,permission) do update set allowed=true,requires_approval=false;
update public.agents set status='enabled',updated_at=now() where agent_key='security';
update public.agent_versions v set lifecycle_state='active',activated_at=coalesce(v.activated_at,now()),activated_by=null where v.id=(select v2.id from public.agent_versions v2 join public.agents a on a.id=v2.agent_id where a.agent_key='security' order by v2.created_at desc limit 1);
comment on table public.security_policies is 'Phase O durable security policy registry. Mutations are server/admin controlled.';
comment on table public.security_requests is 'Phase O durable authorization decisions and approval requests.';
comment on table public.security_events is 'Phase O append-only security event ledger.';
comment on table public.security_incidents is 'Phase O durable security incident lifecycle.';
